L001334	\section{Haar measure and unitary design}
L001335	In this part, we first review the basics of random unitary and design, which would be helpful for the proofs in the later sections.
L001336	We use $\mathcal{H}_d$ to represent the d-dimensional Hilbert space. $\mathcal L(\mathcal H_d)$ is the set of linear operators that act on $\mathcal H_d$. $D(\mathcal{H}_d)$ represents the set of density matrices on $\mathcal{H}_d$. We first define the moment operator.
L001337	
L001338	\begin{definition}[$k$-th Moment operator]
L001339	The $k$-th moment operator, with respect to the probability measure $\nu$, is defined as $\mathcal R_\nu^{(k)}:\mathcal L(\mathcal H_d^{\otimes k})\rightarrow\mathcal L(\mathcal H_d^{\otimes k})$:
L001340	\begin{equation}
L001341	    \mathcal R_\nu^{(k)}(O)=\mathop{\bE}_{U\sim\nu}\left[U^{\otimes k}OU^{\dagger\otimes k}\right],
L001342	\end{equation}
L001343	for all operators in $\mathcal L(\mathcal H_d^{\otimes k})$.
L001344	\end{definition}
L001345	
L001346	Let $S_k$ be the symmetric group of order $k$. For distinct $a_1, \cdots, a_l$, we use the notation $(a_1\cdots a_l)$ to denote a cyclic permutation in $S_k$ , which acts as $a_1\mapsto a_2, \cdots, a_{l-1}\mapsto a_l, a_l\mapsto a_1$. For $\sigma \in S_k$, define a unitary operator $W_\sigma$ acting on $H_d^{\otimes k}$ by
L001347	\begin{equation}
L001348		W_\sigma=\sum_{i_1,\cdots,i_k=1}^d \ketbra{i_{\sigma^{-1}(1)}\cdots i_{\sigma^{-1}(k)}}{i_1\cdots i_k},
L001349	\end{equation}
L001350	where $\{\ket{i}\}_{i=1}^d$ is an orthonormal basis of $\mathcal{H}_d$. One can calculate the $k$-th moment operator using $W_\sigma$, as shown in Lemma \ref{lem: haar_random}.
L001351	
L001352	\begin{lemma}[Theorem 10 in Ref.~\cite{Mele_2024}]\label{lem: haar_random}
L001353		Let $O\in\mathcal L(\mathcal H_d^{\otimes k})$. The moment operator can then be expressed as a linear combination of permutation operators:
L001354		\begin{equation}
L001355			\mathop{\mathbb E}_{U\sim \mathrm{Haar}}\left[U^{\otimes k}OU^{\dagger\otimes k}\right]=\sum_{\sigma\in S_k}c_{\sigma}(O)W_\sigma,
L001356		\end{equation}
L001357	    where the coefficients $c_\sigma(O)$ can be determined by solving the following linear system of $k!$ equations:
L001358	    \begin{equation}
L001359	        \Tr(W_\sigma^\dagger O)=\sum_{\sigma\in S_k}c_\sigma(O)\Tr(W_\sigma^\dagger W_\sigma).
L001360	    \end{equation}
L001361	    This system always has at least one solution.
L001362	\end{lemma}
L001363	A commonly used concept is the unitary $k$-design, defined as follows.
L001364	\begin{definition}[Unitary $k$-design]
L001365		Let $\nu$ be a probability distribution over a set of unitaries $S\subseteq U(d)$. The distribution $\nu$ is unitary $k$-design if and only if:
L001366		\begin{equation}
L001367			\mathop{\mathbb E}_{V\sim\nu}\left[V^{\otimes k}OV^{\dagger \otimes k}\right]=\mathop{\mathbb E}_{U\sim\mathrm{Haar}}\left[U^{\otimes k}OU^{\dagger\otimes k}\right].
L001368		\end{equation}
L001369	    for all $O\in\mathcal L((\mathcal H_d)^{\otimes k})$.
L001370	\end{definition}
L001371	For random Haar random states ($\ket{\psi}=U\ket{\psi_0},U\sim\mathrm{Haar}$), we have the $k$-th moment of states \cite{harrow2013church}.
L001372	\begin{lemma}\label{lem:haar_random}
L001373		For Haar random pure state $\ket{\psi}\in\mathcal{H}_d$, we have
L001374		\begin{equation}
L001375			\mathop{\mathbb E}_{\psi\sim \mathrm{Haar}}\ketbra{\psi}{\psi}^{\otimes k}:=\mathop{\bE}_{U\sim\mathrm{Haar}}U^{\otimes k}\ketbra{0}{0}^{\otimes k}U^{\dagger\otimes k}=\frac{1}{(d+k-1)\cdots(d+1)d}\sum_{\sigma\in S_k}W_\sigma
L001376		\end{equation}
L001377	\end{lemma}
L001378	Similarly we have the definition of state $k$-design.
L001379	\begin{definition}[state $k$-design]
L001380		Let $\nu$ be a probability distribution over a set of states $S\subseteq \mathbb{C}^d$. The distribution $\nu$ is said to be a state $k$-design (or also spherical $k$-designs) if and only if:
L001381		\begin{equation}
L001382			\mathop{\mathbb E}_{\psi\sim\nu}\left[\ketbra{\psi}{\psi}^{\otimes k}\right]=\mathop{\mathbb E}_{\psi\sim\mathrm{Haar}}\left[\ketbra{\psi}{\psi}^{\otimes k}\right].
L001383		\end{equation}
L001384	\end{definition}
