L001405	\begin{lemma}\label{lem: 2ndmoment}
L001406	    The second moment under $\cE(\psi_0)$ of a operator $A\in\mathcal L(\mathcal H_{2^N})$ with decomposition $A=\sum_{\{i\}}a_{\{i\}}P_{\{i\}}$ is
L001407	    \begin{equation}
L001408	        \mathop{\bE}_{\kp\sim\cE(\psi_0)}\bra{\psi}A\kp^2=\left(\frac{\Tr(A)}{d}\right)^2+\sum_{\{i\}\ne\{0\}}a_{\{i\}}^2\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\bigotimes_{r=1}^{N}\left(\frac{2(1-\delta_{i_r0})}{3}\mathbb F+\frac{4\delta_{i_r0}-1}{3}\mathbb I\right)),
L001409	    \end{equation}
L001410	     where $\{i\}$ represents an index string $(i_1i_2\dots i_N)$, and each $i_k=0,1,2,3$ represents $P_{i_k}=I,X,Y,Z$ respectively.
L001411	\end{lemma}
L001412	\begin{proof}
L001413	    The second moment of $A$ is
L001414	    \begin{equation}
L001415	        \begin{aligned}\mathop{\bE}_{\kp\sim\cE(\psi_0)}\bra{\psi}A\kp^2&=\mathop{\bE}_{\kp\sim\cE(\psi_0)}\Tr(\ketbra{\psi}{\psi}^{\otimes 2}A^{\otimes 2})\\
L001416	        &=\mathop{\bE}_{U_1\sim\mathrm{Haar}}\cdots\mathop{\bE}_{U_N\sim\mathrm{Haar}}\Tr(\left(\bigotimes_{r=1}^NU_r\right)^{\otimes 2}\ketbra{\psi_0}{\psi_0}^{\otimes 2}\left(\bigotimes_{r=1}^NU_r^\dagger\right)^{\otimes 2}A^{\otimes 2})\\
L001417	        &=\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\left(\mathop{\bE}_{U_1\sim\mathrm{Haar}}\cdots\mathop{\bE}_{U_N\sim\mathrm{Haar}}\left(\bigotimes_{r=1}^NU_r^\dagger\right)^{\otimes 2}A^{\otimes 2}\left(\bigotimes_{r=1}^NU_r\right)^{\otimes 2}\right))
L001418	        \end{aligned},
L001419	    \end{equation}
L001420	    so we only need to discuss the expectation term in the trace. From
L001421	    \begin{equation}
L001422	         A = \sum_{\{i\}}a_{\{i\}}P_{\{i\}}= \sum_{i_1,i_2,\dots,i_N}a_{i_1,i_2,\dots,i_N}P_{i_1}\otimes P_{i_2}\otimes \cdots P_{i_N} \label{equ: paulidecom}
L001423	    \end{equation}
L001424	    we have
L001425	    \begin{equation}
L001426	        A^{\otimes 2} = \sum_{\{i\}}\sum_{\{j\}}a_{\{i\}}a_{\{j\}}P_{i_1}\otimes P_{i_2} \otimes\cdots P_{i_N}\otimes P_{j_1}\otimes P_{j_2}\otimes\cdots P_{i_N}.
L001427	    \end{equation}
L001428	    The the expectation term becomes
L001429	    \begin{equation}
L001430	        \mathop{\bE}_{U_1\sim\mathrm{Haar}}\cdots\mathop{\bE}_{U_N\sim\mathrm{Haar}}\left(\bigotimes_{r=1}^NU_i^\dagger\right)^{\otimes 2}A^{\otimes 2}\left(\bigotimes_{r=1}^NU_i\right)^{\otimes 2}=\sum_{\{i\}}\sum_{\{j\}}a_{\{i\}}a_{\{j\}}\bigotimes_{r=1}^{N}\left(\mathop{\bE}_{U_r\sim \mathrm{Haar}}U_r^{\dagger\otimes 2}(P_{i_r}\otimes P_{j_r})U_r^{\otimes 2}\right).
L001431	    \end{equation}
L001432	    By Lemma \ref{lem: haar_random}, we have
L001433	    \begin{align}
L001434	        \mathop{\bE}_{U\sim\mathrm{Haar}}[(U^\dagger)^{\otimes 2}(P_i\otimes P_j)U^{\otimes 2}]=\frac{d\Tr(P_iP_j)-\Tr(P_i)\Tr(P_j)}{d(d^2-1)}\mathbb F + \frac{d\Tr(P_j)\Tr(P_i)-\Tr(P_iP_j)}{d(d^2-1)}\mathbb I\label{equ: 2design},
L001435	    \end{align}
L001436	    where $d=2$, $\mathbb F$ represents the two-qubit SWAP gate and $\mathbb I$ is the two-qubit identity. For two single-qubit Pauli operators $P_i,P_j$,
L001437	    \begin{equation}
L001438	        \Tr(P_i)=2\delta_{i0},\quad\Tr(P_j)=2\delta_{j0}, \quad\Tr(P_iP_j)=2\delta_{ij}.
L001439	    \end{equation}
L001440	    Then Eq.~\eqref{equ: 2design} becomes
L001441	    \begin{align}
L001442	        \mathop{\bE}_{U\sim\mathrm{Haar}}[(U^\dagger)^{\otimes 2}(P_i\otimes P_j)U^{\otimes 2}]=\frac{2}{3}(\delta_{ij}-\delta_{i0}\delta_{j0})\mathbb F+\frac{1}{3}(4\delta_{i0}\delta_{j0}-\delta_{ij})\mathbb I.
L001443	    \end{align}
L001444	    Therefore, if $i\ne j$, then the second moment in Eq.~\eqref{equ: 2design} becomes $0$. According to this result, if we are interested in the second moment of $A$, the only terms we need to consider are $\sum_{\{i\}} a_{\{i\}}^2P_{\{i\}}^{\otimes 2}$. When $\{i\}=(00\dots0):=\{0\}$, we have $a_{00\dots0}=\Tr(A)/d$, then the moment becomes
L001445	    \begin{align}
L001446	        \mathop{\bE}_{U_1\sim\mathrm{Haar}}\cdots\mathop{\bE}_{U_N\sim\mathrm{Haar}}\left(\bigotimes_{r=1}^NU_r^\dagger\right)^{\otimes 2}A^{\otimes 2}\left(\bigotimes_{r=1}^NU_r\right)^{\otimes 2}=\left(\frac{\Tr(A)}{d}\right)^2I^{\otimes 2}_{2^N}+\sum_{\{i\}\ne \{0\}}a_{\{i\}}^2\bigotimes_{r=1}^{N}\left(\frac{2(1-\delta_{i_r0})}{3}\mathbb F+\frac{4\delta_{i_r0}-1}{3}\mathbb I\right).\label{equ: commoncase}
L001447	    \end{align}
L001448	    Therefore, the second moment of $A$ under $\cE(\psi_0)$ is
L001449	    \begin{align}
L001450	        \mathop{\bE}_{\kp\sim\cE(\psi_0)}\bra{\psi}A\kp^2&=\Tr(\ketbra{\psi_0}{\psi_0}\left(\mathop{\bE}_{U_1\sim\mathrm{Haar}}\cdots\mathop{\bE}_{U_N\sim\mathrm{Haar}}\left(\bigotimes_{r=1}^NU_r^\dagger\right)^{\otimes 2}A^{\otimes 2}\left(\bigotimes_{r=1}^NU_r\right)^{\otimes 2}\right))\\
L001451	        &=\left(\frac{\Tr(A)}{d}\right)^2+\sum_{\{i\}\ne\{0\}}a_{\{i\}}^2\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\bigotimes_{r=1}^{N}\left(\frac{2(1-\delta_{i_r0})}{3}\mathbb F+\frac{4\delta_{i_r0}-1}{3}\mathbb I\right)).
L001452	    \end{align}
L001453	    \textbf{Remark}: Actually this Lemma only needs that each $U_i$ is selected from a unitary 2-design ensemble to meet Eq.~\eqref{equ: 2design}.
L001454	\end{proof}
L001455	Now we give the proof of Theorem 1 in the main text, restated as follows.
L001456	\begin{theorem}\label{theo:var-ent}
L001457	    For a given $n$-qubit state $\ket{\psi_0}$, we consider the main term of Trotter error $E=\sum E_j$ and the ensemble $\cE(\psi_0)=\{(\bigotimes_{r=1}^nU_i)\ket{\psi_0}\}$, where each $U_i$ is a random gate of one qubit chosen over a unitary 2-design, then the variance of $s_E(\psi)=\bra{\psi}E^\dagger E\ket{\psi}$ is bounded by the trace distance between the reduced density matrix of $\ket{\psi_0}$ on some subsystem indexed by $j,j'$ and the maximally mixed state $I/d_{jj'}$,
L001458	    \begin{align}
L001459	        \mathop{\mathrm{Var}}_{\ket{\psi}\sim\cE(\psi_0)}[s_E(\psi)] \leq \sum_{j\le j'}a_{jj'}\Tr\left|\rho_{jj'}-\frac{I}{d_{jj'}}\right|.
L001460	    \end{align}
L001461	    One can also use the entanglement entropy $S(\rho)=-\Tr[\rho\log(\rho)]$ to rewrite the bound as
L001462	    \begin{align}
L001463	        \mathop{\mathrm{Var}}_{\ket{\psi}\sim\cE(\psi_0)}[s_E(\psi)] \leq \sum_{j\le j'}a_{jj'}\sqrt{2\log(d_{jj'})-2S(\rho_{jj'})}.
L001464	    \end{align}
L001465	    which indicates that the upper bound of the variance of the squared Trotter error decreases with the increasing of entanglement of the initial state.
L001466	    The coefficient $a_{jj'}=2\Tr(\widetilde{E_{jj'}}\widetilde{E^\dagger E})/d$, where $\widetilde A:=\sum_{P\in\cP_N}\abs{\Tr(PA)}P/d$ and
L001467	    \begin{equation}
L001468	        E_{jj'}:=\frac{E_{j'}^\dagger E_j+E_j^\dagger E_{j'}-\Tr(E_{j'}^\dagger E_j+E_j^\dagger E_{j'})I/d}{1+\delta_{jj'}}.\label{equ: Ejj'}
L001469	    \end{equation}
L001470	    We define $\supp(jj')=\supp(E_{jj'})$, $\rho_{jj'}=\Tr_{[N]\setminus\supp(jj')}(\ketbra{\psi_0}{\psi_0})$ and $d_{jj'}=2^{\abs{\supp(jj')}}$.
L001471	\end{theorem}
L001472	\begin{proof}
L001473	    From Lemma \ref{lem: 1-design}, $\cE(\psi_0)$ is 1-design, so the expectation is \cite{zhao_hamiltonian_2022}
L001474	    \begin{equation}
L001475	        \mathop{\bE}_{\ket{\psi}\sim\cE(\psi_0)} s_E(\psi)=\|E\|_F^2.
L001476	    \end{equation}
L001477	    We can decompose $E^\dagger E$ as
L001478	    \begin{equation}
L001479	        E^\dagger E=\norm{E}_F^2I_{2^N}+\sum_{\{s\}}b_{\{s\}}P_{\{s\}},\label{equ: paulidec}
L001480	    \end{equation}
L001481	    then from Lemma \ref{lem: 2ndmoment}, the variance is
L001482	    \begin{align}
L001483	         \mathop{\mathrm{Var}}_{\ket{\psi}\sim\cE(\psi_0)}[s_E(\psi)] &= \mathop {\bE}_{\ket{\psi}\sim\cE(\psi_0)} \bra{\psi}E^\dagger E\ket{\psi}^2-\left(\mathop {\bE}_{\ket{\psi}\sim\cE(\psi_0)} \bra{\psi}E^\dagger E\ket{\psi}\right)^2\notag\\
L001484	         &=\left(\frac{\Tr(E^\dagger E)}{d}\right)^2+\sum_{\{s\}}b_{\{s\}}^2\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\bigotimes_{r=1}^{N}\left(\frac{2(1-\delta_{s_r0})}{3}\mathbb F+\frac{4\delta_{s_r0}-1}{3}\mathbb I\right))-\|E\|_F^4\notag\\ &=\sum_{\{s\}}b_{\{s\}}^2\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\bigotimes_{r=1}^{N}\left(\frac{2(1-\delta_{s_r0})}{3}\mathbb F+\frac{4\delta_{s_r0}-1}{3}\mathbb I\right))\notag\\
L001485	         &=\sum_{\{s\}}b_{\{s\}}^2\Tr(\ketbra{\psi_0}{\psi_0}^{\otimes 2}\mathcal F_{\supp(\{s\})}\otimes I_{[N]\setminus\supp(\{s\})}^{\otimes 2}),\label{equ: varresult}
