L001567	\section{Kurtosis and Magic}
L001568	To characterize the statistical properties of states with identical magic, we apply random Clifford gates to the initial state. Given that the random Clifford group forms a unitary 3-design, the first three moments of $\bra{\psi}E^\dagger E\ket{\psi}$ can be computed directly using Haar-random results for any given error term $E$, independent of the initial state $\psi_0$.Therefore, the fourth moment is of particular interest. We compute it as presented in Lemma \ref{lem:4moment}.
L001569	\begin{lemma}\label{lem:4moment}
L001570	    The 4th moment of $s_E(\psi)$ under $\cM(\psi_0)$ is
L001571	    \begin{equation}
L001572	        \mathop{\bE}_{\ket{\psi}\in\cM(\psi_0)} s_E(\psi)^4= \frac{24d(B-A)+6(1-M)[(d^2+3d)A-4B]}{4d(d-1)(d+1)(d+2)(d+4)},\label{equ:4moment}
L001573	    \end{equation}
L001574	    where
L001575	    \begin{equation}
L001576	        \begin{aligned}
L001577	            A = \Tr[\Pi_4^{sym}(E^{\dagger} E)^{\otimes 4} Q],\quad
L001578	            B = \Tr[\Pi_4^{sym}(E^{\dagger} E)^{\otimes 4}],\quad
L001579	            Q = \frac{1}{d^2}\sum_{P\in\mathcal P_N}P^{\otimes 4}.
L001580	        \end{aligned}\label{equ: ABQ}
L001581	    \end{equation}
L001582	    Here $\Pi_4^{sym}$ is the projector onto the totally symmetric space $\mathrm{Sym}_4(\mathbb C^d)$ and $M$ is the magic of the state $\ket{\psi_0}$.
L001583	\end{lemma}
L001584	\begin{proof}
L001585	    The 4th-moment function of  states in $\cM(\psi_0)$ is \cite{zhu2016clifford}
L001586	\begin{equation}
L001587	    \mathop{\bE}_{\ket{\psi}\sim \cM(\psi_0)}  \ketbra{\psi}{\psi}^{\otimes 4}=\beta_+Q\Pi^{sym}_4+\beta_-(1-Q)\Pi^{sym}_4
L001588	\end{equation}
L001589	where $Q$ and $\Pi^{sym}_4$ are defined in Eq.~\eqref{equ: ABQ}, and
L001590	\begin{equation}
L001591	    \begin{aligned}
L001592	        \beta_+&=\frac{6}{(d+1)(d+2)}\Tr[Q\Pi_4^{sym}(\ketbra{\psi}{\psi}^{\otimes 4})]\\
L001593	        \beta_-&=\frac{24}{(d-1)(d+1)(d+2)(d+4)}\left(1-\Tr[Q\Pi_4^{sym}(\ketbra{\psi}{\psi}^{\otimes 4})]\right)
L001594	    \end{aligned}\label{equ: betas}.
L001595	\end{equation}
L001596	By definition, we have
L001597	\begin{equation}
L001598	    \Pi_4^{sym}\ketbra{\psi}{\psi}^{\otimes 4}=\ketbra{\psi}{\psi}^{\otimes 4},
L001599	\end{equation}
L001600	then the trace in Eq.~\ref{equ: betas} becomes
L001601	\begin{equation}
L001602	    \Tr[Q\Pi_4^{sym}(\ketbra{\psi}{\psi}^{\otimes 4})]=\Tr[Q(\ketbra{\psi}{\psi}^{\otimes 4})]=\frac{1}{d^2}\sum_{P\in\cP_N}|\bra{\psi}P\ket{\psi}|^4=\frac{1}{d}(1-M).
L001603	\end{equation}
L001604	Here $M=1-\frac{1}{d}\sum_{P\in\cP_N}|\bra{\psi}P\ket{\psi}|^4$ is the magic of state $\ket{\psi}$. Then we have
L001605	\begin{equation}
L001606	    \mathop{\mathbb E}_{\ket{\psi}\in\cM(\psi_0)}\ket{\psi}\bra{\psi}^{\otimes 4}=\frac{6(1-M)(d-1)(d+4)-24(d-1-M)d}{d(d-1)(d+1)(d+2)(d+4)}Q\Pi_4^{sym}+\frac{24(d-1-M)}{(d-1)(d+1)(d+2)(d+4)}\Pi_4^{sym}.
L001607	\end{equation}
L001608	Thus, the 4th-moment of $s_E$ obtains
L001609	    \begin{equation}
L001610	        \begin{aligned}
L001611	            \mathop{\bE}_{\ket{\psi}\in \cM(\psi_0)}s_E(\psi)^4&=\mathop{\bE}_{\ket{\psi}\in\cM(\psi_0)}\Tr\left[(E^\dagger E)^{\otimes 4}\ket{\psi}\bra{\psi}^{\otimes 4}\right]=\Tr\left[(E^\dagger E)^{\otimes 4}\mathop{\bE}_{\ket{\psi}\in\cM(\psi_0)}\ket{\psi}\bra{\psi}^{\otimes 4}\right]\\
L001612	            &=\frac{6(d-1)(d+4)(1-M)-24(d-1-M)}{d(d^2-1)(d+2)(d+4)}A+\frac{24(d-1-M)}{d(d^2-1)(d+2)(d+4)}B\\
L001613	            &=6\times\frac{(d^2+3d)(1-M)A-4dA+4dB-4B(1-M_{lin})}{d(d^2-1)(d+2)(d+4)}\\
L001614	            &=\frac{24d(B-A)+6(1-M_{lin})\left[(d^2+3d)A-4B\right]}{d(d^2-1)(d+2)(d+4)},
L001615	        \end{aligned}
L001616	    \end{equation}
L001617	    where $A,B$ is defined in Eq.~\eqref{equ: ABQ}.
L001618	\end{proof}
L001619	Through Lemma \ref{lem:4moment}, we find that the fourth moment of $s_E(\psi)$ exhibits a linear dependence on magic for a given set of states with identical magic $M$. In practice, the error term $E$ we typically observe takes a form similar to $\sum a_jQ_j$, where each $Q_j$ is a local Pauli operator and each $a_j$ is a constant coefficient. Now by analyzing the sign of the dominant term in the coefficients of Eq.\eqref{equ:4moment}, we establish a negative linear relationship between the fourth moment of $s_E(\psi)$ and $M$ when $n$ is large. See Lemma \ref{lem:coeff}. Before presenting Lemma \ref{lem:coeff}, we first introduce an auxiliary result, Fact \ref{fact: unchange}.
