L001676	\begin{proof}
L001677	    Calculating B directly, we get
L001678	    \begin{equation}
L001679	        24B = 6\Tr[(E^\dagger E)^4]+8\Tr[(E^\dagger E)^3]\Tr(E^\dagger E)+3\Tr[(E^\dagger E)^2]^2+6\Tr[(E^\dagger E)^2]\Tr(E^\dagger E)^2+\Tr(E^\dagger E)^4\label{equ:B}
L001680	    \end{equation}
L001681	    and
L001682	    \begin{equation}
L001683	        \begin{aligned}
L001684	            24A = \frac{1}{d^2}&\sum_{P\in\mathcal P_N}(6\Tr[(E^\dagger EP)^4]+8\Tr[(E^\dagger EP)^3]\Tr(E^\dagger EP)+3\Tr[(E^\dagger EP)^2]^2\\
L001685	            &+6\Tr[(E^{\dagger} EP)^2]\Tr(E^\dagger EP)^2+\Tr(E^\dagger EP)^4)
L001686	        \end{aligned}.\label{equ:A}
L001687	    \end{equation}
L001688	    \begin{enumerate}[(a)]
