L001690	        \begin{align}
L001691	            E^\dagger E&=\sum_{i=1}^{m} a_i^2 I+2\sum_{\substack{i\neq j\\Q_{ij}=Q_{ji}}} a_ia_jQ_iQ_j=\Theta(m)I+\sum\alpha_{ij}Q_{ij},N\rightarrow \infty\label{equ:EE}\\
L001692	            \Rightarrow &\Tr(E^\dagger E)=\Theta(m)d=\mathrm{poly}(N)2^{N},N\rightarrow\infty
L001693	        \end{align}
L001694	        Here $\alpha_{ij}:=2a_ia_j$ and $Q_{ij}:=Q_iQ_j$. Therefore, the coefficients in the second part are all constants, i.e. $|\alpha_{ij}|=\Theta(1)$ and there are $\mathcal O(m^2)$ terms in total. Then
L001695	        \begin{align}
L001696	            (E^\dagger E)^2&=\left((\sum a_i^2)^2+4\sum \alpha_{ij}^2\right)I+4(\sum a_i^2)^2\left(\sum\alpha_{ij}Q_{ij}\right)+8\sum_{\substack{ij\neq kn\\Q_{ijkn}=Q_{knij}}}\alpha_{ij}\alpha_{kn}Q_{ij}Q_{kn}\\
