L001767	    \begin{equation}
L001768	        \mathop{\bE}_{\ket{\psi}\sim\cM}\ket{\psi}\bra{\psi}^{\otimes k}=\mathop{\bE}_{\ket{\psi}\sim\mathrm{Haar}}\ket{\psi}\bra{\psi}^{\otimes k},\quad\forall k\le3.
