L001771	    \begin{align}
L001772	        m_1&=\mathop{\bE}_{\ket{\psi}\sim\cM}\bra{\psi}E^\dagger E\ket{\psi}=\frac{\Tr(E^\dagger E)}{d}\\
L001773	        m_2&=\mathop{\bE}_{\ket{\psi}\sim\cM}\bra{\psi}E^\dagger E\ket{\psi}^2=\frac{\Tr(E^\dagger E)^2+\Tr[(E^\dagger E)^2]}{d(d+1)}\\
