L001777	    \begin{equation}
L001778	            \mathop{\mathrm{Var}}_{\ket{\psi}\sim\cM}\left(\bra{\psi}E^\dagger E\ket{\psi}\right)=m_2-m_1^2
L001779	    \end{equation}
L001780	    and the fourth central moment
L001781	    \begin{equation}
L001782	        \begin{aligned}
