L001820	    formal linear relation implied by Lemma~\ref{lem:4moment}, the data are well described by
L001821	    a linear function of magic. The fitted slope is negative for the system
L001822	    and parameters considered here, although the sign of this long-time
L001823	    coefficient is not fixed by our current analytical proof.}
L001824	    \label{fig:longtimekur}
L001825	\end{figure}
L001826	
L001827	We emphasize, however, that Lemma~\ref{lem:4moment} by itself only establishes the linear dependence, not the sign of the coefficient \(\beta_{\mathrm{LT}}\). In Theorem~\ref{theo:formerkurtosis}, the negativity of the corresponding coefficient for the leading-order Trotter error was obtained using magnitude estimates specific to the perturbative, one-step error operator. These estimates no longer apply once \(E\) is replaced by the accumulated long-time error \(E_{\mathrm{LT}}\), whose operator content is generated by the full dynamics. Thus, our present analytical argument does not determine whether \(\beta_{\mathrm{LT}}\) is positive or negative in the long-time regime.
L001828	
L001829	We therefore examine this question numerically. As shown in Fig.~\ref{fig:longtimekur}, for step size \(\delta t=0.1\) and \(r=100\) Trotter steps, the long-time magic--kurtosis relation remains approximately linear, and the fitted slope is negative (The accumulated error is generated using the same QIMF Hamiltonian as in the main text). This indicates that, for the physical systems and parameters studied here, higher magic continues to correlate with a smaller kurtosis of the long-time Trotter-error distribution. The observed negative slope should be viewed as numerical evidence rather than a rigorous consequence of our current proof.
L001830	\subsection{Long-time entanglement-variance relation}
L001831	For a long-time Trotter error, we can bound its error using the triangle inequality of norms.
L001832	\begin{fact}
L001833	    For a long-time simulation task, we cut $t$ into $r$ small pieces, then the error satisfies
L001834	    \begin{equation}
L001835	        \norm{(\sU_p(\delta t)^r-\sU_0(t))\ket{\psi_0}}
L001836	        \le\sum_{k=0}^{r-1}\norm{(\sU_p(\delta t)-\sU_0(\delta t))\sU_p(\delta t)^k\ket{\psi_0}}.
L001837	    \end{equation}
L001838	\end{fact}
L001839	\begin{proof}
L001840	    We derive this lemma by triangle inequality
L001841	    \begin{equation}
L001842	        \begin{aligned}
L001843	            \norm{(\sU_p(\delta t)^r-\sU_0(t))\ket{\psi_0}}
L001844	            &=\norm{\left(\sU_p(\delta t)^r-\sU_0(\delta t)\sU_p(\delta t)^{r-1}+\sU_0(\delta t)\sU_p(\delta t)^{r-1}-\sU_0(\delta t)^r\right)\ket{\psi_0}}\\
L001845	            &\le \norm{(\sU_p(\delta t)-\sU_0(\delta t))\sU_p(\delta t)^{r-1}\ket{\psi_0}}+\norm{(\sU_p(\delta t)^{r-1}-\sU_0(\delta t)^{r-1})\ket{\psi_0}}\\
L001846	            &\le....\\
L001847	            &\le\sum_{k=0}^{r-1}\norm{(\sU_p(\delta t)-\sU_0(\delta t))\sU_p(\delta t)^k\ket{\psi_0}}
L001848	        \end{aligned}
L001849	    \end{equation}
L001850	\end{proof}
L001851	For simplicity, we denote $\sum_{k=0}^{r-1}\norm{(\sU_p(\delta t)-\sU_0(\delta t))\sU_p(\delta t)^k\ket{\psi_0}}$ as $e_r$. When $\delta t$ is small enough, we can ignore the higher-order terms in $\sU_p(\delta t)-\sU_0(\delta t)$ and have
L001852	\begin{equation}
L001853	    e_r\approx\sum_{k=0}^{r-1}\norm{E\sU_p(\delta t)^k\ket{\psi}}\delta t^{p+1}=\delta t^{p+1}\sum_{k=0}^{r-1}\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi})}.
L001854	\end{equation}
L001855	And we can prove that the variance of $e_r$ has the following inequality.
L001856	\begin{lemma}\label{aplem:sum_var}
L001857	The variance of $e_r$ satisfies
L001858	    \begin{equation}
L001859	        \mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}(e_r)\le r\delta t^{2p+2}\sum_{k=0}^{r-1}\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi})}\right]
L001860	    \end{equation}
L001861	\end{lemma}
L001862	\begin{proof}
L001863	    \begin{align}
L001864	    \mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}(e_r)=&\delta t^{2p+2}\sum_{k=0}^{r-1}\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi}}\right]+\delta t^{2p+2}\sum_{k\ne l}\mathop{\operatorname{Cov}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi}},\sqrt{s_E(\sU_p(\delta t)^l\ket{\psi}}\right]\notag\\
L001865	    \le&\delta t^{2p+2}\sum_{k=0}^{r-1}\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi}}\right]\\
L001866	    &+\delta t^{2p+2}\sum_{k\ne l}\sqrt{\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi}}\right]\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^l\ket{\psi}}\right]}\notag\\
L001867	    \le&\frac{1}{2}\delta t^{2p+2}\sum_{k,l}\left(\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi}}\right]+\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^l\ket{\psi}}\right]\right)\\
L001868	    =&r\delta t^{2p+2}\sum_{k=0}^{r-1}\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi})}\right]
L001869	    \end{align}
L001870	\end{proof}
L001871	For each term in the summation, we have the following lemma.
L001872	\begin{lemma}\label{aplem:sqrt_X_var}
L001873	Given a bounded positive random variable $X$, the variance of $\sqrt{X}$ is bouned by
L001874	    \begin{equation}
L001875	        \operatorname{Var}(\sqrt{X})\le\frac{1}{\sqrt 2}\sqrt{\operatorname{Var}(X)}.
L001876	    \end{equation}
L001877	\end{lemma}
L001878	\begin{proof}
L001879	Assume that there is an another random variable $Y$ i.d.d. with $X$, then
L001880	    \begin{align}
L001881	        \operatorname{Var}(\sqrt{X})=&\frac{1}{2}\bE\left((\sqrt{X}-\sqrt Y)^2\right)
L001882	        \le \frac{1}{2}\bE\left(\abs{X-Y}\right)
L001883	        \le \frac{1}{2}\sqrt{\bE\left((X-Y)^2\right)}=\frac{1}{\sqrt 2}\sqrt{\operatorname{Var}(X)}.
L001884	    \end{align}
L001885	\end{proof}
L001886	By combining Theorem \ref{theo:var-ent} with the two preceding lemma, we arrive at Theorem 3 in the main text. We define $S_k=\{s\subseteq[N]|s=\operatorname{supp}(\sU_p^{\dagger k}E_j^\dagger E_{j'}\sU_p^k),\forall j,j'\}$ as the set of supports for each term in the expansion of operator $\sU_p^{\dagger k}E^\dagger E\sU_p^k$. Subsequently, we establish the following theorem.
L001887	\begin{theorem}
L001888	    Given a state $\ket{\psi_0}$ with entanglement structure $S(\rho_A)$, neglecting the influence of higher-order terms in $\delta t$, the variance of the $p$-th order Trotter error under $\cE(\psi_0)$ satisfies
L001889	    \begin{equation}
L001890	        \mathop{\operatorname{Var}}_{\kp\sim\cE(\psi_0)}[e_r]\le r\delta t^{2p+2}\sum_{k=0}^{r-1}\sqrt{\sum_{s\in S_k}c_{s}\sqrt{\log d_{s}-S(\rho_{s})}},
L001891	    \end{equation}
L001892	    where $c_s$ denotes a constant that is independent of $\psi_0$.
L001893	\end{theorem}
L001894	\begin{proof}
L001895	    From Theorem \ref{theo:var-ent},
L001896	    \begin{equation}
L001897	    \mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[{s_E(\sU_p(\delta t)^k\ket{\psi})}\right]=\mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[{s_{E\sU_p(\delta t)^k}(\ket{\psi})}\right]\le\sum_{j\le j'}a^{(k)}_{jj'}\sqrt{2\log{d^{(k)}_{jj'}}-2S(\rho^{(k)}_{jj'})}.
L001898	    \end{equation}
L001899	    It should be noted that the constants $a_{jj'}^{(k)}$ and the support of $\rho_{jj'}^{(k)}$ here are different from those in Theorem \ref{theo:var-ent}; they are obtained by replacing the error matrix $E$ with $E\sU_p(\delta t)^k$ respectively. The support of $\sU_p(\delta t)^{\dagger k}E^\dagger E\sU_p(\delta t)^k$ linearly grows with $k$ as $\sU_p(\delta t)$ has the brickwork architecture consisting of several local unitary. Therefore, the results still exhibits the property that the entanglement of $\psi_0$ reduces the variance. Combining Lemma \ref{aplem:sqrt_X_var},
L001900	    \begin{equation}
L001901	        \mathop{\operatorname{Var}}_{\psi\sim\cE(\psi_0)}\left[\sqrt{s_E(\sU_p(\delta t)^k\ket{\psi})}\right]\le\frac{1}{\sqrt 2}\sqrt{\sum_{j\le j'}a^{(k)}_{jj'}\sqrt{2\log{d^{(k)}_{jj'}}-2S(\rho^{(k)}_{jj'})}},
L001902	    \end{equation}
L001903	    and Lemma \ref{aplem:sum_var},
L001904	    \begin{align}
L001905	        \mathop{\operatorname{Var}}_{\kp\sim\cE(\psi_0)}[e_r]\le &r\delta t^{2p+2}\sum_{k=0}^{r-1}\frac{1}{\sqrt 2}\sqrt{\sum_{j\le j'}a^{(k)}_{jj'}\sqrt{2\log{d^{(k)}_{jj'}}-2S(\rho^{(k)}_{jj'})}}\\
L001906	        =&r\delta t^{2p+2}\sum_{k=0}^{r-1}\sqrt{\sum_{s\in S_k}c_s\sqrt{\log d_{s}-S(\rho_{s})}},
L001907	    \end{align}
L001908	    where the summation $\sum_{A_k}$ sums over the supports of $\sU_p(\delta t)^{\dagger k}E_j^\dagger E_{j'}\sU_p(\delta t)^k$s.
L001909	\end{proof}
